(ns futon3c.diagramprover.wm-wire-producer-wm-wire-flight-run-flight-driver-summary-readings-test-liter
  (:require [clojure.edn :as edn] [clojure.java.io :as io] [clojure.test :refer [deftest is testing]] [futon2.aif.flight-driver :as fd] [futon3c.diagramprover.wm-wire :as w])
  (:import [java.security MessageDigest]))
(def producer 'futon3c.diagramprover.wm-wire-producer-wm-wire-flight-run-flight-driver-summary-readings-test-liter-test)
(def operation ['futon2.aif.flight-driver/run-flight! 'futon2.aif.flight/run!])
(def wire-id [:flight-run :flight-driver-summary :readings])
(defn- observe [text] (let [r (fd/run-flight! {:target "M-wire-driver" :repo "futon3c" :path "holes/missions/M-wire.md" :read-text (fn [& _] text) :store (w/tmp-dir "wire-store") :run-record-dir (w/tmp-dir "wire-run-records") :sources {} :answer-fn (fn [_] {:state "declined" :seat "wire-seat" :job-id "wire-job-1"}) :max-clicks 1 :click-fn (fn [_] {:click-id "wire-click-1" :unreached-wants []})} {:flight-id "flight-wire-driver"})] {:writer (:readings (:flight r)) :reader (:readings (:flight r)) :projection (:readings r) :status (:status r)}))
(def base "A mission text with no recognised criteria.\n")
(defn build-record [] {:producer producer :operation operation :inputs {:mission-text base :different-text "Exit criteria:\n- [ ] the gate is green\n"} :wires {wire-id {:primary (observe base) :different (observe "Exit criteria:\n- [ ] the gate is green\n")}} :left-out {:temporary-paths "fresh hermetic store and run-record directories"}})
(def stem "wm-wire-flight-run-flight-driver-summary-readings-test-liter")
(defn- text [x] (str (pr-str x) "\n"))
(defn- sha [s] (apply str (map #(format "%02x" (bit-and % 255)) (.digest (MessageDigest/getInstance "SHA-256") (.getBytes s "UTF-8")))))
(defn- files [] (filter #(.startsWith (.getName %) (str stem "@")) (.listFiles (io/file "test/fixtures/wire-producers"))))
(defn- write! [r] (let [s (text r) f (io/file "test/fixtures/wire-producers" (str stem "@" (subs (sha s) 0 12) ".edn"))] (when (.exists f) (throw (ex-info "record exists" {}))) (spit f s) (println f)))
(defn- leaves [x] (letfn [(walk [p v] (if (map? v) (mapcat (fn [[k z]] (walk (conj p k) z)) v) [p]))] (walk [] x)))
(deftest producer-test (let [a (build-record)] (if (= "1" (System/getenv "WM_WIRE_PRODUCER_WRITE")) (write! a) (let [fs (files)] (is (= 1 (count fs))) (let [e (edn/read-string (slurp (first fs)))] (doseq [p (leaves e)] (testing (pr-str p) (is (= (get-in e p) (get-in a p))))))))))
